<?php if (!defined('ABSPATH')) exit('No direct script access allowed');/*======================================================================*\|| #################################################################### |||| # The Classes configurations of the MaxxCMS                        # |||| # MaxxCMS 6.0.0 code by Bui Van Thiem (vanthiembui.it@gmail.com)   # |||| # ---------------------------------------------------------------- # |||| # All PHP code in this file is ©2007-2014 MaxCMS.                  # |||| # This file may not be redistributed in whole or significant part. # |||| # ---------------- MaxxCMS IS NOT FREE SOFTWARE ----------------    # |||| #################################################################### ||\*======================================================================*/class Helper {	static function cal($num, $percent){		if((float) $num > 0 && (float) $percent > 0)			return $num * $percent / 100;		return 0;	}	static function percent($a, $b){		if((float) $a > 0 && (float) $b > 0)			return round($a / $b, 2) * 100;		return 0;	}	function getHtmlGrowth($a, $b){		$per = 100;		$symbol = '~';		if($a > $b){			$diff = $a-$b;			$symbol = '+';			$per = $diff/$b*100;		} else if($a < $b){			$diff = $b - $a;			$symbol = '-';			$per = $diff/$b * 100;		}		return sprintf('%s %s', $symbol, round($per,1).'%');	}	function getHtmlGrowthV2($a, $b){		$per = 0.0;		$symbol = '~';		$icon = "right-arrow-alt";		$textcolor = "text-muted";		if($a > $b && $b > 0){			$diff = $a-$b;			$symbol = '+';			$per = $diff/$b*100;			$icon = "up-arrow-alt";			$textcolor = "text-success";		} else if($a < $b && $a > 0){			$diff = $b - $a;			$symbol = '-';			$per = $diff/$b * 100;			$icon = "down-arrow-alt";			$textcolor = "text-danger";		} else if($a > $b && $b==0) {			$symbol = '+';			$per = 100;			$icon = "up-arrow-alt";			$textcolor = "text-success";		}		$html_content = sprintf('%s %s', $symbol, round($per,1).'%');		return sprintf('<small class="%s fw-medium"><i class="bx bx-%s"></i> %s</small>', $textcolor, $icon, $html_content);	}	function getFieldValue($field, $source = array(), $def=""){		if(isset($source[$field]) && !empty($source[$field]))			return $source[$field];		return $def;	}	function splitIntoThreeRanges($n, $floor) {		if($n < 1) {			return [				'thap' => [],				'trung' => [],				'cao' => []			][$floor];		} else {			$chunk = floor($n / 3);			$remainder = $n % 3;			$low_end = $chunk;			$medium_end = $chunk * 2;			$high_end = $n;			if ($remainder >= 1) $low_end += 1;			if ($remainder == 2) $medium_end += 1;			return [				'thap' => range(1, $low_end),				'trung' => range($low_end + 1, $medium_end),				'cao' => range($medium_end + 1, $high_end)			][$floor];		}	}	function viTriCuaXX($chuoi) {		global $core, $dbcoon, $clsISO;		// Nếu không có "XX" thì trả về sớm		$pos = strpos($chuoi, 'XX');		if ($pos === false) {			return '_notfound';		}		// Trường hợp có dấu phân cách		if (strpos($chuoi, '-') !== false) {			$parts = explode('-', $chuoi);			if (in_array('XX', $parts)) {				if(count($parts) == 2){					if (isset($parts[1]) && $parts[1] === 'XX') {						return "_last";					}				} else {					if (isset($parts[1]) && $parts[1] === 'XX') {						return "_center";					} elseif (isset($parts[2]) && $parts[2] === 'XX') {						return "_last";					}				}			}		} else if (strpos($chuoi, '.') !== false) {			$parts = explode('.', $chuoi);			if (count($parts) === 2) {				$suffix = $parts[1];				if (strpos($suffix, 'XX') === 0) {					return "_center";				} elseif (substr($suffix, -2) === 'XX') {					return "_last";				}			}		} else {			// Trường hợp không có dấu phân cách			$length = strlen($chuoi);			if ($pos === 0) {				return "_first";			} elseif ($pos + 2 === $length) {				return "_last";			} elseif ($pos + 2 < $length) {				return "_center";			} else {				return "_notfound";			}		}	}	function formatXCode($code){		global $core, $dbcoon, $clsISO;		if($code == '04') return '05A';		if($code == '07') return '08A';		if($code == '13') return '12A';		if($code == '14') return '15A';		if($code == '17') return '18A';	}	function loan_calculate(array $opt) {		global $core, $clsISO;		// ============================================================		// 1. INPUT		// ============================================================		$total_price   = floatval($opt['total_price']);		$loan_rate     = floatval($opt['loan_rate']);		$loan_amount   = $total_price * $loan_rate / 100;		$total_months  = intval($opt['total_months']);		// Ưu đãi		$promo_months  = intval($opt['promo_months'] ?? 0);		$promo_rate    = floatval($opt['promo_interest'] ?? 0) / 12 / 100;		$after_rate    = floatval($opt['after_interest'] ?? 0) / 12 / 100;		if ($promo_months <= 0 || $promo_rate <= 0) {			$promo_months = 0;			$promo_rate   = 0;		}		$method        = $opt['method'] ?? 'equal_principal';		if (!in_array($method, ['equal_principal', 'annuity'], true)) {			$method = 'equal_principal';		}		$grace_months  = intval($opt['grace_months'] ?? 0);		// Hỗ trợ lãi		$support_rate   = floatval($opt['interest_support_rate'] ?? 0) / 100;		$support_months = intval($opt['interest_support_months'] ?? 0);		// Tất toán sớm		$early_fee_rate = floatval($opt['early_payment_fee_rate'] ?? 0) / 100;		$settle_month   = intval($opt['settle_month'] ?? 0);		// ============================================================		// 2. KHỞI TẠO		// ============================================================		$remaining        = $loan_amount;		$first_payment    = 0;		$interest_promo   = 0;		$principal_promo  = 0;		$interest_after   = 0;		$principal_after  = 0;		$monthly_promo    = 0;		$monthly_after    = 0;		$down_payment     = $total_price - $loan_amount;		$early_fee_value  = 0;		$schedule         = [];		// ============================================================		// 3. EQUAL_PRINCIPAL: tính gốc cố định/tháng		//    FIX 2026-05-13: chia trên (total - grace) thay vì total		//    để đảm bảo tất toán hết khoản vay khi có ân hạn gốc.		// ============================================================		$amortize_months = max($total_months - $grace_months, 1);		$equal_principal = $loan_amount / $amortize_months;		// ============================================================		// 4. ANNUITY: tính PMT ưu đãi (chỉ dùng khi method=annuity)		//    Lưu ý: PMT này được dùng trong phase promo (sau grace).		//    Phase after sẽ tính lại PMT dựa trên remaining + after_months		//    → tự amortize đúng dù có grace.		// ============================================================		if ($method === 'annuity' && $promo_months > 0) {			if ($promo_rate > 0) {				$monthly_promo = $loan_amount *					($promo_rate * pow(1 + $promo_rate, $total_months)) /					(pow(1 + $promo_rate, $total_months) - 1);			} else {				$monthly_promo = $loan_amount / $total_months;			}		}		// ============================================================		// 5. VÒNG ƯU ĐÃI (tháng 1 → promo_months)		// ============================================================		for ($m = 1; $m <= $promo_months; $m++) {			if ($settle_month > 0 && $m > $settle_month) break;			$begin_balance = $remaining;			// Lãi tháng này (có thể được hỗ trợ giảm bởi support_rate)			$interest = $remaining * $promo_rate;			if ($m <= $support_months) {				$interest *= (1 - $support_rate);			}			// Ân hạn gốc → chỉ trả lãi			if ($m <= $grace_months) {				$principal = 0;				$payment   = $interest;			} else {				if ($method === 'equal_principal') {					$principal = $equal_principal;					$payment   = $principal + $interest;				} else {					// annuity					$principal = $monthly_promo - $interest;					$payment   = $monthly_promo;				}			}			$remaining -= $principal;			if ($m === 1) $first_payment = $payment;			$interest_promo  += $interest;			$principal_promo += $principal;			$schedule[] = [				'month'         => $m,				'begin_balance' => $begin_balance,				'interest'      => $interest,				'principal'     => $principal,				'payment'       => $payment,				'remaining'     => max($remaining, 0),				'is_promo'      => 1,			];		}		// ============================================================		// 6. TẤT TOÁN SỚM TRONG GIAI ĐOẠN ƯU ĐÃI		//    Bổ sung schedule entry cho tháng tất toán + cộng vào totals.		// ============================================================		if ($settle_month > 0 && $settle_month <= $promo_months) {			// Phí phạt			$early_fee_value = $remaining * $early_fee_rate;			$settle_payment  = $remaining + $early_fee_value;			// Ghi entry settle vào schedule (consistency với case settle after)			$schedule[] = [				'month'         => $settle_month,				'begin_balance' => $remaining,				'interest'      => 0,				'principal'     => $remaining,				'payment'       => $settle_payment,				'remaining'     => 0,				'is_promo'      => 1,				'early_fee'     => $early_fee_value,			];			$principal_promo += $remaining;			return [				'method'              => $method,				'loan_amount'         => $loan_amount,				'down_payment'        => $down_payment,				'first_payment'       => $first_payment,				'monthly_promo'       => $monthly_promo,				'monthly_after'       => 0,				'interest_promo'      => $interest_promo,				'principal_promo'     => $principal_promo,				'interest_after'      => 0,				'principal_after'     => 0,				'total_payment_promo' => $interest_promo + $principal_promo,				'total_payment_after' => 0,				'total_interest'      => $interest_promo,				'total_principal'     => $principal_promo,				'total_payment'       => $interest_promo + $principal_promo + $early_fee_value,				'remaining'           => 0,				'early_fee_value'     => $early_fee_value,				'schedule'            => $schedule,			];		}		// ============================================================		// 7. GIAI ĐOẠN SAU ƯU ĐÃI (tháng promo_months+1 → total_months)		// ============================================================		$after_months = $total_months - $promo_months;		if ($method === 'annuity' && $after_months > 0) {			if ($after_rate > 0) {				$monthly_after = $remaining *					($after_rate * pow(1 + $after_rate, $after_months)) /					(pow(1 + $after_rate, $after_months) - 1);			} else {				$monthly_after = $remaining / $after_months;			}		}		for ($i = 1; $i <= $after_months; $i++) {			$current_month = $promo_months + $i;			if ($settle_month > 0 && $current_month > $settle_month) break;			$begin_balance = $remaining;			$interest = $remaining * $after_rate;			if ($method === 'equal_principal') {				$principal = $equal_principal;				// Tháng cuối: clear toàn bộ remaining (tránh sai số làm tròn)				if ($i === $after_months) {					$principal = $remaining;				}				$payment = $principal + $interest;			} else {				$principal = $monthly_after - $interest;				$payment   = $monthly_after;			}			$remaining -= $principal;			if ($first_payment === 0) $first_payment = $payment;			$interest_after  += $interest;			$principal_after += $principal;			$schedule[] = [				'month'         => $current_month,				'begin_balance' => $begin_balance,				'interest'      => $interest,				'principal'     => $principal,				'payment'       => $payment,				'remaining'     => max($remaining, 0),				'is_promo'      => 0,			];		}		// ============================================================		// 8. TẤT TOÁN SỚM SAU GIAI ĐOẠN ƯU ĐÃI		// ============================================================		if ($settle_month > 0 && $settle_month > $promo_months) {			// Lãi của tháng tất toán			$interest_last   = $remaining * $after_rate;			// Phí phạt			$early_fee_value = $remaining * $early_fee_rate;			// Tổng tiền phải trả = gốc còn lại + lãi tháng đó + phí phạt			$settle_payment  = $remaining + $interest_last + $early_fee_value;			$schedule[] = [				'month'         => $settle_month,				'begin_balance' => $remaining,				'interest'      => $interest_last,				'principal'     => $remaining,				'payment'       => $settle_payment,				'remaining'     => 0,				'is_promo'      => 0,				'early_fee'     => $early_fee_value,			];			$interest_after  += $interest_last;			$principal_after += $remaining;			$remaining        = 0;		}		// ============================================================		// 9. OUTPUT		// ============================================================		$total_payment_promo = $principal_promo + $interest_promo;		$total_payment_after = $principal_after + $interest_after;		return [			'method'              => $method,			'loan_amount'         => $loan_amount,			'down_payment'        => $down_payment,			'first_payment'       => $first_payment,			'monthly_promo'       => $monthly_promo,			'monthly_after'       => $monthly_after,			'interest_promo'      => $interest_promo,			'principal_promo'     => $principal_promo,			'interest_after'      => $interest_after,			'principal_after'     => $principal_after,			'total_payment_promo' => $total_payment_promo,			'total_payment_after' => $total_payment_after,			'total_interest'      => $interest_promo + $interest_after,			'total_principal'     => $principal_promo + $principal_after,			'total_payment'       => $interest_promo + $interest_after +									 $principal_promo + $principal_after + $early_fee_value,			'remaining'           => max($remaining, 0),			'early_fee_value'     => $early_fee_value,			'schedule'            => $schedule,		];	}}